"""G9 Stage H: Python reference tests for verify.py / occlusion.py / display.py closeup_display (fixture regenerated by make_verify_fixture.py)."""
import json, os, sys
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", ".."))
from ml.eval.verify import h2_decision, verify_identity, user_confirm, part_agreement, stageh_decision, FROZEN_VERIFY
from ml.eval.occlusion import occlusion_reasons, FROZEN_OCC
F = json.load(open(os.path.join(os.path.dirname(__file__), "fixtures", "verify_parity.json")))


def test_fixture_reproduces():
    assert F["frozen_verify"] == FROZEN_VERIFY and F["frozen_occ"] == FROZEN_OCC
    for c in F["h2"]: assert h2_decision(c["probs"], c["p"]) == c["out"]
    for c in F["verify"]: assert verify_identity(c["wide"], c["h1"], c["probs"], c["p"]) == c["out"]
    for c in F["confirm"]: assert user_confirm(c["v"], c["chosen"]) == c["out"]
    for c in F["part"]: assert part_agreement(c["halves"], c["classId"], c["minP"]) == c["out"]
    for c in F["occ"]: assert occlusion_reasons(c["cues"], c["p"]) == c["out"]
    for c in F["decision"]: assert stageh_decision(c["v"], c["occ"], c["gs"], c["gr"], c["en"]) == c["out"]


def test_uncertain_or_contradictory_never_graded():
    wide = dict(status="identified", classId=1)
    for p in ([0.3, 0.35] + [0] * 10 + [0.35], [0, 0.02, 0, 0.95] + [0] * 8 + [0.03]):
        v = verify_identity(wide, None, p, FROZEN_VERIFY)
        assert v["status"] == "unable"
        d = stageh_decision(v, [], "graded", [], True)
        assert d["outcome"] == "unable_to_identify" and d["gradeShown"] is None and d["priceKind"] is None


def test_no_grade_display_in_stage_h():
    d = stageh_decision(dict(status="verified", classId=1, evidence="wide+h2"), [], "graded", [])
    assert d["outcome"] == "quality_check_unavailable" and d["gradeShown"] is None


def test_closeup_display_blocks_grades():
    from ml.prices.display import closeup_display, GRADE_DISPLAY_ENABLED
    C = json.load(open(os.path.join(os.path.dirname(__file__), "fixtures", "closeup_parity.json")))
    assert GRADE_DISPLAY_ENABLED is False
    for oc in ("quality_check_unavailable", "not_graded", "graded"):
        v = closeup_display("verified", "apple", "Apple", oc, C["price_sources"], "2026-10-14")
        assert v["gradeShown"] is False
        if v["price"]["show"]: assert v["price"]["line"]["kind"] == "category_reference" and v["price"]["line"]["listGrade"] is None
    assert closeup_display("unable", "apple", "Apple", "graded", C["price_sources"], "2026-10-14")["price"]["show"] is False
